/* ========================================
   WellStream Platform — Global Styles
   ======================================== */

:root {
  --primary-navy: #15295A;
  --accent-green: #6CC24A;
  --dark-gray: #3C424B;
  --bg-dark: #0D1B2A;
  --bg-card: #1B2838;
  --bg-card-hover: #223449;
  --text-primary: #E8EEF4;
  --text-secondary: #9FB3C8;
  --text-muted: #6B8BAE;
  --accent-teal: #00B4D8;
  --accent-blue: #0077B6;
  --border-color: #2A3F55;
  --success: #6CC24A;
  --warning: #F4A261;
  --error: #E63946;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.25);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.35);
  --shadow-lg: 0 16px 48px rgba(0,0,0,0.45);
  --transition-fast: 0.15s ease;
  --transition-base: 0.3s ease;
  --transition-slow: 0.5s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--bg-dark);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-teal);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-green);
}

img {
  max-width: 100%;
  display: block;
}

/* ========================================
   Typography
   ======================================== */

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: clamp(1rem, 2vw, 1.25rem); }

p {
  color: var(--text-secondary);
  max-width: 65ch;
}

.label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent-green);
}

/* ========================================
   Buttons
   ======================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent-teal), var(--accent-blue));
  color: #fff;
  box-shadow: 0 4px 16px rgba(0, 180, 216, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(0, 180, 216, 0.45);
  color: #fff;
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--accent-teal);
  color: var(--accent-teal);
}

.btn-accent {
  background: var(--accent-green);
  color: #0D1B2A;
  font-weight: 700;
}

.btn-accent:hover {
  background: #7dd85a;
  color: #0D1B2A;
}

/* ========================================
   Layout Containers
   ======================================== */

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 5rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.section-header h2 {
  margin-bottom: 0.75rem;
}

.section-header p {
  margin: 0 auto;
  font-size: 1.0625rem;
}

/* ========================================
   Navigation
   ======================================== */

.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-color);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--accent-green);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--transition-fast);
}

.nav-links a:hover {
  color: var(--text-primary);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
}

.nav-dropdown-toggle:hover {
  color: var(--text-primary);
}

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: -1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.5rem;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  box-shadow: var(--shadow-md);
  list-style: none;
}

.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-menu a {
  display: block;
  padding: 0.625rem 1rem;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.nav-dropdown-menu a:hover {
  background: var(--bg-card-hover);
  color: var(--text-primary);
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
}

/* ========================================
   Hero
   ======================================== */

.hero {
  position: relative;
  padding: 10rem 0 6rem;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 20% 50%, rgba(0, 180, 216, 0.08) 0%, transparent 50%),
              radial-gradient(ellipse at 80% 20%, rgba(108, 194, 74, 0.06) 0%, transparent 50%);
  pointer-events: none;
}

.hero .container {
  position: relative;
  z-index: 1;
}

.hero-content {
  max-width: 800px;
}

.hero h1 {
  margin-bottom: 1.25rem;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-teal) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  color: var(--text-secondary);
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* ========================================
   Cards & Grids
   ======================================== */

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 2rem;
  transition: all var(--transition-base);
}

.card:hover {
  border-color: var(--accent-teal);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--accent-teal), var(--accent-blue));
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: #fff;
  font-size: 1.25rem;
}

.card h3 {
  margin-bottom: 0.5rem;
  font-size: 1.125rem;
}

.card p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

/* ========================================
   Tabs
   ======================================== */

.tabs {
  margin-top: 2rem;
}

.tab-list {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 0.75rem 1.25rem;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  margin-bottom: -1px;
}

.tab-btn:hover {
  color: var(--text-primary);
}

.tab-btn.active {
  color: var(--accent-teal);
  border-bottom-color: var(--accent-teal);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========================================
   Accordion
   ======================================== */

.accordion {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.accordion-item {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition-base);
}

.accordion-item:hover {
  border-color: var(--border-color);
}

.accordion-item.active {
  border-color: var(--accent-teal);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  cursor: pointer;
  background: none;
  border: none;
  width: 100%;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
}

.accordion-header .icon {
  width: 24px;
  height: 24px;
  transition: transform var(--transition-base);
  color: var(--accent-teal);
  flex-shrink: 0;
}

.accordion-item.active .accordion-header .icon {
  transform: rotate(180deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.accordion-item.active .accordion-body {
  max-height: 500px;
  padding: 0 1.5rem 1.5rem;
}

.accordion-body p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

/* ========================================
   Stats
   ======================================== */

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  text-align: center;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
}

.stat-ring {
  width: 140px;
  height: 140px;
  position: relative;
}

.stat-ring svg {
  transform: rotate(-90deg);
  width: 100%;
  height: 100%;
}

.stat-ring-bg {
  fill: none;
  stroke: var(--border-color);
  stroke-width: 8;
}

.stat-ring-fill {
  fill: none;
  stroke: url(#statGradient);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 377;
  stroke-dashoffset: 377;
  transition: stroke-dashoffset 1.5s ease;
}

.stat-ring-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-primary);
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  max-width: 220px;
}

/* ========================================
   Timeline
   ======================================== */

.timeline {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.timeline-item {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.5rem;
}

.timeline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.timeline-header h4 {
  color: var(--accent-teal);
  font-size: 1.125rem;
}

.timeline-header span {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 600;
}

.timeline-bar {
  height: 8px;
  background: var(--border-color);
  border-radius: 4px;
  overflow: hidden;
}

.timeline-bar-fill {
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-green));
  transition: width 1.2s ease;
}

/* ========================================
   Testimonials
   ======================================== */

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.testimonial-slide {
  min-width: 100%;
  padding: 0 0.5rem;
}

.testimonial-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 2.5rem;
  text-align: center;
}

.testimonial-card blockquote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text-primary);
  margin-bottom: 1.5rem;
  line-height: 1.5;
}

.testimonial-card cite {
  font-style: normal;
  color: var(--accent-teal);
  font-weight: 600;
  font-size: 0.9375rem;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-color);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--accent-teal);
  width: 28px;
  border-radius: 5px;
}

/* ========================================
   Forms
   ======================================== */

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  margin-bottom: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.875rem 1rem;
  background: var(--bg-card);
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.9375rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent-teal);
  box-shadow: 0 0 0 3px rgba(0, 180, 216, 0.15);
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: var(--text-muted);
}

.form-group .error-msg {
  display: none;
  font-size: 0.8125rem;
  color: var(--error);
  margin-top: 0.375rem;
}

.form-group.error input,
.form-group.error select,
.form-group.error textarea {
  border-color: var(--error);
}

.form-group.error .error-msg {
  display: block;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0 1.5rem;
}

.form-success {
  text-align: center;
  padding: 3rem 2rem;
}

.form-success h3 {
  color: var(--accent-green);
  margin-bottom: 0.75rem;
}

/* ========================================
   Diagrams
   ======================================== */

.diagram-container {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 3rem;
  text-align: center;
}

.diagram-pillars {
  display: flex;
  justify-content: center;
  gap: 2rem;
  flex-wrap: wrap;
  margin-top: 2rem;
}

.diagram-pillar {
  flex: 1;
  min-width: 240px;
  max-width: 320px;
  background: linear-gradient(180deg, var(--bg-card-hover), var(--bg-card));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 2rem;
  position: relative;
  transition: all var(--transition-base);
}

.diagram-pillar:hover {
  border-color: var(--accent-teal);
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}

.diagram-pillar .pillar-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-teal), var(--accent-blue));
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
  color: #fff;
  font-size: 1.5rem;
}

.diagram-pillar h4 {
  margin-bottom: 0.5rem;
  font-size: 1.125rem;
}

.diagram-pillar p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

.diagram-connections {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1rem;
  margin: 1.5rem 0;
  flex-wrap: wrap;
}

.diagram-hub {
  background: linear-gradient(135deg, var(--accent-green), #4a9e2f);
  color: #0D1B2A;
  padding: 1rem 2rem;
  border-radius: var(--radius-lg);
  font-weight: 700;
  font-size: 1.125rem;
}

/* Data lifecycle diagram */
.lifecycle-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.lifecycle-stages {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0;
  flex-wrap: wrap;
}

.lifecycle-stage {
  background: var(--bg-card-hover);
  border: 1px solid var(--border-color);
  padding: 1rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  position: relative;
}

.lifecycle-stage:first-child {
  border-radius: var(--radius-sm) 0 0 var(--radius-sm);
}

.lifecycle-stage:last-child {
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

.lifecycle-stage:not(:last-child)::after {
  content: '';
  position: absolute;
  right: -12px;
  top: 50%;
  transform: translateY(-50%);
  border: 6px solid transparent;
  border-left-color: var(--accent-teal);
  z-index: 2;
}

/* ========================================
   Cookie Banner
   ======================================== */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--bg-card);
  border-top: 1px solid var(--border-color);
  padding: 1.25rem 0;
  z-index: 999;
  transform: translateY(100%);
  transition: transform var(--transition-base);
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.cookie-banner p {
  font-size: 0.9375rem;
  margin: 0;
}

.cookie-banner .btn-group {
  display: flex;
  gap: 0.75rem;
  flex-shrink: 0;
}

/* ========================================
   Footer
   ======================================== */

.footer {
  background: #070F1A;
  border-top: 1px solid var(--border-color);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 2.5rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-primary);
  margin-bottom: 1.25rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.625rem;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--accent-teal);
}

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ========================================
   Featured Banner
   ======================================== */

.featured-banner {
  background: linear-gradient(135deg, var(--primary-navy), #0f1d33);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.featured-banner h3 {
  font-size: 1.5rem;
  margin-bottom: 0.25rem;
}

.featured-banner p {
  color: var(--accent-teal);
  font-weight: 600;
}

/* ========================================
   Responsive
   ======================================== */

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .hero {
    padding: 8rem 0 4rem;
  }

  .hero h1 {
    font-size: 2rem;
  }

  .hero p {
    font-size: 1rem;
  }

  .section {
    padding: 3rem 0;
  }

  .card-grid {
    grid-template-columns: 1fr;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

